// Validate input + normalize brief data
const body = $input.first().json.body || {};
const briefId = body.briefId || `br-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
const title = (body.title || '').trim().slice(0, 200);
const summary = (body.summary || '').trim().slice(0, 2000);
const contributors = Array.isArray(body.contributors) ? body.contributors.slice(0, 4) : ['coo', 'cmo', 'cfo', 'cco'];

if (!title) {
  throw new Error('title_required');
}
if (!summary) {
  throw new Error('summary_required');
}

return {
  briefId,
  title,
  summary,
  contributors,
  receivedAt: Date.now(),
  callbackUrl: body.callbackUrl || 'https://gerai.mahewwork.com/api/agent/briefs?action=result',
};

parameters.jsonBody:
={
  "role": "{{ $json.contributors }}",
