  "briefContext": "{{ $('Validate + Normalize').item.json.title }}"
}

parameters.jsCode:
// Build assembled context untuk Atmaja synthesis
const all = $input.all();
const replies = all[0].json.data || [];
const meta = $('Validate + Normalize').first().json;

const lines = replies.map(r => {
  const role = (r.role || 'unknown').toUpperCase();
  const text = (r.text || '').slice(0, 1500);
  return `### ${role}\n${text}`;
}).join('\n\n');

return {
  briefId: meta.briefId,
  title: meta.title,
  summary: meta.summary,
  callbackUrl: meta.callbackUrl,
  csuiteOutput: lines,
  synthPrompt: `Sintesakan output 4 C-suite ini untuk brief \"${meta.title}\" jadi 1 keputusan utama, 3 next action konkret, dan 1 risiko terbesar. Maximum 300 kata.\n\n${lines}`,
};

// Build final AgentOutputEnvelope payload
const synth = $input.first().json;
const meta = $('Build Atmaja Synth Prompt').first().json;

return {
  briefId: meta.briefId,
  status: synth.ok ? 'completed' : 'degraded',
  result: {
    summary: synth.text || 'Atmaja synthesis tidak tersedia',
    csuiteOutput: meta.csuiteOutput,
    model: synth.model || 'unknown',
    title: meta.title,
    originalSummary: meta.summary,
    completedAt: Date.now(),
  },
  callbackUrl: meta.callbackUrl,
};

parameters.responseBody:
={
